SELECT DATE_FORMAT(stores.opened_date, 'yyyy-MM') AS opened_month, stores.region, SUM(CASE WHEN orders.status = 'SHIPPED' THEN 1 ELSE 0 END) AS shipped_count FROM orders JOIN stores ON orders.store_id = stores.id LEFT JOIN customers ON customers.id = orders.customer_id WHERE orders.shipping_fee < 13 GROUP BY DATE_FORMAT(stores.opened_date, 'yyyy-MM'), stores.region HAVING shipped_count >= 66;
